//! Move → sound-effect table: a transcription of `MoveSoundTable` from the
//! original game's `data/moves/sfx.asm`, plus a port of the `GetMoveSound` /
//! `IsCryMove` routines from `engine/battle/animations.asm`.
//!
//! Each row is `(sfx id, pitch mod, tempo mod)`. In the original ROM the sfx
//! id indexes the audio banks' header tables; here the id is in the
//! `pokered_audio::sfx_data::SfxId` id space (header-entry order, as
//! generated by `tools/asm2sfx.py`). `pitch_mod`/`tempo_mod` are the
//! ROM-verbatim `wFrequencyModifier`/`wTempoModifier` bytes; the audio
//! engine currently does not apply them (see docs/FIDELITY_GAPS.md).
//!
//! Verified byte-for-byte (pitch/tempo) and id-for-id (sfx) against the
//! disassembly by `scripts/verify_move_sfx_data.py`.

use crate::moves::MoveId;
use crate::species::Species;

/// One `MoveSoundTable` row: `db SFX_*, pitch_mod, tempo_mod`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MoveSfx {
    /// Base SFX id (`SfxId` id space).
    pub sfx: u8,
    /// `wFrequencyModifier` addend (unapplied — see module docs).
    pub pitch_mod: u8,
    /// `wTempoModifier` addend (unapplied — see module docs).
    pub tempo_mod: u8,
}

/// The sound a move-animation command plays, per `GetMoveSound`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MoveSound {
    /// Play this SFX id (`SfxId` id space).
    Sfx(u8),
    /// `IsCryMove` (GROWL/ROAR): play the whose-turn mon's cry instead
    /// (`GetCryData` on `wBattleMonSpecies`/`wEnemyMonSpecies`). The
    /// command's MoveSoundTable row bytes are ADDED to the cry's own
    /// pitch/length modifiers (the `add [hl]` in `GetMoveSound`).
    Cry {
        species: Species,
        pitch_mod: u8,
        tempo_mod: u8,
    },
}

