/// `GetMoveSound` (engine/battle/animations.asm): resolve the sound for an
/// animation command's sound byte.
///
/// * `anim_move` — `wAnimationID`: the move whose animation is playing.
/// * `sound_move` — the command's sound field: a move id, 0 = NO_MOVE
///   (the original stores NO_MOVE - 1 in the command stream and skips
///   playing anything).
/// * `attacker_species` — species of the whose-turn mon (`hWhoseTurn`).
///
/// Returns `None` when the command plays no sound. For GROWL/ROAR
/// (`IsCryMove`) every command sound becomes the attacker's cry, with the
/// command's table row bytes added to the cry's pitch/length modifiers
/// (`wFrequencyModifier`/`wTempoModifier`).
pub fn get_move_sound(
    anim_move: MoveId,
    sound_move: u8,
    attacker_species: Species,
) -> Option<MoveSound> {
    if sound_move == 0 {
        return None;
    }
    // IsCryMove: carry set when wAnimationID is GROWL or ROAR.
    if matches!(anim_move, MoveId::Growl | MoveId::Roar) {
        let entry = MOVE_SFX_TABLE.get(sound_move as usize - 1)?;
        return Some(MoveSound::Cry {
            species: attacker_species,
            pitch_mod: entry.pitch_mod,
            tempo_mod: entry.tempo_mod,
        });
    }
    // Table is indexed by the command-stream byte = move id - 1.
    let entry = MOVE_SFX_TABLE.get(sound_move as usize - 1)?;
    Some(MoveSound::Sfx(entry.sfx))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_length_matches_num_attacks_plus_tail() {
        // NUM_ATTACKS = 165 (STRUGGLE); +1 trailing row in the asm table.
        assert_eq!(MOVE_SFX_TABLE.len(), 166);
    }

    #[test]
    fn spot_check_entries() {
        // POUND: db SFX_POUND, $00, $80 (SfxId::Pound = 105).
        assert_eq!(
            MOVE_SFX_TABLE[MoveId::Pound as usize - 1],
            MoveSfx { sfx: 105, pitch_mod: 0x00, tempo_mod: 0x80 }
        );
        // STRUGGLE: db SFX_BATTLE_0B, $00, $80 (SfxId::Battle0B = 106).
        assert_eq!(
            MOVE_SFX_TABLE[MoveId::Struggle as usize - 1],
            MoveSfx { sfx: 106, pitch_mod: 0x00, tempo_mod: 0x80 }
        );
    }

    #[test]
    fn get_move_sound_table_lookup() {
        // TACKLE (0x21): SFX_SUPER_EFFECTIVE = 121.
        assert_eq!(
            get_move_sound(MoveId::Tackle, MoveId::Tackle as u8, Species::Rattata),
            Some(MoveSound::Sfx(121))
        );
        // NO_MOVE sound byte plays nothing.
        assert_eq!(get_move_sound(MoveId::Pound, 0, Species::Rattata), None);
    }

    #[test]
    fn get_move_sound_cry_moves() {
        // IsCryMove: GROWL/ROAR animations play the attacker's cry, even
        // for command sound bytes naming other moves; the command row's
        // pitch/tempo bytes are added to the cry's modifiers.
        let growl = &MOVE_SFX_TABLE[MoveId::Growl as usize - 1];
        assert_eq!(
            get_move_sound(MoveId::Growl, MoveId::Growl as u8, Species::Pikachu),
            Some(MoveSound::Cry {
                species: Species::Pikachu,
                pitch_mod: growl.pitch_mod,
                tempo_mod: growl.tempo_mod,
            })
        );
        let pound = &MOVE_SFX_TABLE[MoveId::Pound as usize - 1];
        assert_eq!(
            get_move_sound(MoveId::Roar, MoveId::Pound as u8, Species::Onix),
            Some(MoveSound::Cry {
                species: Species::Onix,
                pitch_mod: pound.pitch_mod,
                tempo_mod: pound.tempo_mod,
            })
        );
    }
}
